import { v2 as cloudinary } from "cloudinary";
import env from "../config/env.js";
import ApiError from "../utils/ApiError.js";

// All medical documents are stored in PRIVATE ("authenticated") Cloudinary storage: a plain URL
// never works; only signed, short-lived URLs generated by this server do. PDFs and images are
// uploaded with resource_type "image" (Cloudinary supports PDF there).
const DELIVERY = { resource_type: "image", type: "authenticated" };

let override;
/** Test hook: replace Cloudinary with a fake ({ upload, destroy, signedUrl }). */
export const setCloudinaryForTests = (fake) => {
  override = fake;
};

export const isCloudinaryConfigured = () =>
  Boolean(env.cloudinary.cloudName && env.cloudinary.apiKey && env.cloudinary.apiSecret);

function client() {
  if (!isCloudinaryConfigured()) {
    throw new ApiError(503, "File storage (Cloudinary) is not configured on the server");
  }
  cloudinary.config({
    cloud_name: env.cloudinary.cloudName,
    api_key: env.cloudinary.apiKey,
    api_secret: env.cloudinary.apiSecret,
    secure: true,
  });
  return cloudinary;
}

/** Uploads an in-memory buffer. Returns the metadata that is saved in MongoDB. */
export async function uploadDocument(buffer, { ownerId }) {
  if (override) return override.upload(buffer, { ownerId });
  const c = client();
  try {
    const result = await new Promise((resolve, reject) => {
      const stream = c.uploader.upload_stream(
        { ...DELIVERY, folder: `${env.cloudinary.folder}/${ownerId}`, use_filename: false, unique_filename: true, overwrite: false },
        (err, res) => (err ? reject(err) : resolve(res))
      );
      stream.end(buffer);
    });
    return { publicId: result.public_id, resourceType: result.resource_type, format: result.format, size: result.bytes };
  } catch (err) {
    console.error("Cloudinary upload failed:", err.message);
    throw new ApiError(502, "Could not upload the document to cloud storage. Please try again");
  }
}

/** Best-effort removal (used to clean up when the database write that follows an upload fails). */
export async function deleteDocument(doc) {
  if (!doc?.publicId) return;
  try {
    if (override) return await override.destroy(doc);
    await client().uploader.destroy(doc.publicId, { ...DELIVERY, invalidate: true });
  } catch (err) {
    console.error("Cloudinary cleanup failed for", doc.publicId, err.message);
  }
}

/** Short-lived (default 2 minutes) signed download URL. The secret never leaves the server. */
export function signedDocumentUrl(doc, downloadName) {
  const expiresAt = Math.floor(Date.now() / 1000) + env.cloudinary.signedUrlTtlSeconds;
  if (override) return override.signedUrl(doc, expiresAt);
  const c = client();
  return c.utils.private_download_url(doc.publicId, doc.format, {
    ...DELIVERY,
    expires_at: expiresAt,
    attachment: downloadName ? downloadName.replace(/[^\w.-]/g, "_") : true,
  });
}
